    it("uses custom reason in InventoryError message", async () => {
      const cart = new Cart();
      cart.add(product(), 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: false, reason: "discontinued" }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
