      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };
      const cart = new Cart();
      cart.add(product(), 1);

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        RangeError,
      );
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh + inventory + async tax + discount + shipping", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US-CA",
      });
      cart.add(product({ id: "item1" }), 2);

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // price refreshed to 2000 → subtotal = 2000*2 = 4000
      expect(result.totals.subtotalCents).toBe(4000);
      // discount = 10% of 4000 = 400
      expect(result.totals.discountCents).toBe(400);
      // discounted = 3600, tax = 8% of 3600 = 288
      expect(result.totals.taxCents).toBe(288);
      // shipping = flat 500
      expect(result.totals.shippingCents).toBe(500);
      // total = 3600 + 288 + 500 = 4388
      expect(result.totals.totalCents).toBe(4388);

      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("item1");
      expect(inventoryChecker.check).toHaveBeenCalledWith("item1", 2);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("checkout without collaborators uses sync pipeline", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
    });

    it("returns lines in the result", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const result = await cart.checkout();
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].quantity).toBe(2);
    });
  });
});

