    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.9)).toThrow(RangeError);
    });

    it("accepts valid params", () => {
      expect(() => new FlatShippingCalculator(500, 5000)).not.toThrow();
    });

    it("accepts 0 flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([makeLine("a")], 1000)).toBe(500);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a")], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a")], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal below free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a")], 4999)).toBe(500);
    });

    it("returns flat fee when no freeOverCents configured", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([makeLine("a")], 99999)).toBe(799);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 100 }], -1),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 100 }], 5.5),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 for zero-weight items", () => {
      expect(calc.computeShippingCents([makeLine("a", 0, 1)], 1000)).toBe(0);
    });

    it("returns 0 for items with no weight", () => {
      expect(calc.computeShippingCents([makeLine("a", undefined, 1)], 1000)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      expect(calc.computeShippingCents([makeLine("a", 300)], 1000)).toBe(300);
    });

    it("selects first bracket at exact boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
    });

    it("selects second bracket just above first boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(500);
    });

    it("selects last bracket at its boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 5000)], 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(calc.computeShippingCents([makeLine("a", 5001)], 1000)).toBe(2000);
    });

    it("uses last bracket cost as overflow when overflowCostCents not set", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      expect(
        calcNoOverflow.computeShippingCents([makeLine("a", 2000)], 1000),
      ).toBe(500);
    });

    it("sums weight across multiple lines with quantity", () => {
      // 2 items at 300g each = 600g → second bracket
      expect(
        calc.computeShippingCents([makeLine("a", 300, 2)], 1000),
      ).toBe(500);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g → first bracket (500g) after sort → 300
      expect(unsorted.computeShippingCents([makeLine("a", 400)], 0)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities for the same product", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      cart.add(product(), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("throws on non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 0)).toThrow(RangeError);
      expect(() => cart.add(product(), -1)).toThrow(RangeError);
    });

    it("throws on non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 1.5)).toThrow(RangeError);
    });

    it("throws on negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product({ unitPriceCents: -1 }), 1)).toThrow(
        RangeError,
      );
    });
  });

  describe("remove", () => {
    it("removes a product and returns true", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(cart.remove("p1")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("unknown")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product(), 3);
      cart.updateQuantity("p1", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(product(), 3);
      cart.updateQuantity("p1", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 5)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(() => cart.updateQuantity("p1", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      cart.add(product({ id: "p2", name: "Gadget" }), 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of cart lines", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("p1");
      expect(snap[0].quantity).toBe(2);
    });

    it("mutations to snapshot do not affect cart", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(product({ id: "a", unitPriceCents: 500 }), 2);
      cart.add(product({ id: "b", unitPriceCents: 300 }), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(1900);
    });

    it("applies discount via injected policy", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(200);
      expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(1000);
    });

    it("clamps discount to [0, subtotal]", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(9999),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product({ unitPriceCents: 500 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product({ unitPriceCents: 500 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      // tax is computed on discounted subtotal: 1000 - 200 = 800
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
      expect(totals.taxCents).toBe(80);
    });

    it("computes shipping against discounted subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
      expect(totals.shippingCents).toBe(500);
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(72),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      // subtotal=1000, discount=100, discounted=900, tax=72, shipping=500
      expect(totals.totalCents).toBe(900 + 72 + 500);
    });

    it("empty cart returns all zeros", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("uses default region US when not specified", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(product(), 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(
        expect.any(Number),
        "US",
      );
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(product(), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(product(), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    });

    it("throws RangeError when fetcher returns negative price", async () => {
      const cart = new Cart();
      cart.add(product(), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-1),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws RangeError when fetcher returns non-integer price", async () => {
      const cart = new Cart();
      cart.add(product(), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product(), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "price service down",
      );
    });
  });

  describe("inventory check", () => {
    it("succeeds when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product(), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledWith("p1", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when product unavailable", async () => {
      const cart = new Cart();
      cart.add(product(), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false, availableQuantity: 0 }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("p1");
        expect(invErr.requested).toBe(2);
        expect(invErr.available).toBe(0);
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product(), 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 3 }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("p1");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(3);
      }
    });

    it("uses custom reason in InventoryError message", async () => {
      const cart = new Cart();
      cart.add(product(), 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: false, reason: "discontinued" }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        "discontinued",
      );
    });

    it("checks inventory for each line - first denial wins", async () => {
      const cart = new Cart();
      cart.add(product({ id: "a", name: "A" }), 1);
      cart.add(product({ id: "b", name: "B" }), 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, availableQuantity: 0 }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("b");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({ region: "US" });
      cart.add(product({ unitPriceCents: 1000 }), 1);

      const result = await cart.checkout({ asyncTaxProvider });
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
      expect(result.totals.taxCents).toBe(100); // 10% of 1000
    });

    it("async tax applied on discounted subtotal", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "FR",
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);

      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=1000, discount=200, discounted=800, tax=10% of 800=80
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    });

    it("propagates async tax provider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      const cart = new Cart();
      cart.add(product(), 1);

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("throws RangeError for invalid async tax rate", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };
      const cart = new Cart();
      cart.add(product(), 1);

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        RangeError,
      );
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh + inventory + async tax + discount + shipping", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US-CA",
      });
      cart.add(product({ id: "item1" }), 2);

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // price refreshed to 2000 → subtotal = 2000*2 = 4000
      expect(result.totals.subtotalCents).toBe(4000);
      // discount = 10% of 4000 = 400
      expect(result.totals.discountCents).toBe(400);
      // discounted = 3600, tax = 8% of 3600 = 288
      expect(result.totals.taxCents).toBe(288);
      // shipping = flat 500
      expect(result.totals.shippingCents).toBe(500);
      // total = 3600 + 288 + 500 = 4388
      expect(result.totals.totalCents).toBe(4388);

      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("item1");
      expect(inventoryChecker.check).toHaveBeenCalledWith("item1", 2);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("checkout without collaborators uses sync pipeline", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
    });

    it("returns lines in the result", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const result = await cart.checkout();
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].quantity).toBe(2);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { refreshPrices, InventoryError, type PriceFetcher } from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("refreshPrices", () => {
  const makeLine = (id: string, price: number, qty = 1): CartLine => ({
    product: { id, name: id, unitPriceCents: price },
