import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    });

    it("throws RangeError when fetcher returns negative price", async () => {
      const cart = new Cart();
      cart.add(product(), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-1),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws RangeError when fetcher returns non-integer price", async () => {
      const cart = new Cart();
      cart.add(product(), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product(), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "price service down",
      );
    });
  });

  describe("inventory check", () => {
    it("succeeds when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product(), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledWith("p1", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when product unavailable", async () => {
      const cart = new Cart();
      cart.add(product(), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false, availableQuantity: 0 }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("p1");
        expect(invErr.requested).toBe(2);
        expect(invErr.available).toBe(0);
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product(), 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 3 }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("p1");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(3);
      }
    });

    it("uses custom reason in InventoryError message", async () => {
      const cart = new Cart();
      cart.add(product(), 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: false, reason: "discontinued" }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        "discontinued",
      );
    });

    it("checks inventory for each line - first denial wins", async () => {
      const cart = new Cart();
      cart.add(product({ id: "a", name: "A" }), 1);
      cart.add(product({ id: "b", name: "B" }), 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, availableQuantity: 0 }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("b");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({ region: "US" });
      cart.add(product({ unitPriceCents: 1000 }), 1);

      const result = await cart.checkout({ asyncTaxProvider });
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
      expect(result.totals.taxCents).toBe(100); // 10% of 1000
    });

    it("async tax applied on discounted subtotal", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "FR",
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);

      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=1000, discount=200, discounted=800, tax=10% of 800=80
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    });

    it("propagates async tax provider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      const cart = new Cart();
      cart.add(product(), 1);

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("throws RangeError for invalid async tax rate", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };
      const cart = new Cart();
      cart.add(product(), 1);

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        RangeError,
      );
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh + inventory + async tax + discount + shipping", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US-CA",
      });
      cart.add(product({ id: "item1" }), 2);

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // price refreshed to 2000 → subtotal = 2000*2 = 4000
      expect(result.totals.subtotalCents).toBe(4000);
      // discount = 10% of 4000 = 400
      expect(result.totals.discountCents).toBe(400);
      // discounted = 3600, tax = 8% of 3600 = 288
      expect(result.totals.taxCents).toBe(288);
      // shipping = flat 500
      expect(result.totals.shippingCents).toBe(500);
      // total = 3600 + 288 + 500 = 4388
      expect(result.totals.totalCents).toBe(4388);

      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("item1");
      expect(inventoryChecker.check).toHaveBeenCalledWith("item1", 2);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("checkout without collaborators uses sync pipeline", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
    });

    it("returns lines in the result", async () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const result = await cart.checkout();
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].quantity).toBe(2);
    });
  });
});
"}

