toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities for the same product", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      cart.add(product(), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("throws on non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 0)).toThrow(RangeError);
      expect(() => cart.add(product(), -1)).toThrow(RangeError);
    });

    it("throws on non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 1.5)).toThrow(RangeError);
    });

    it("throws on negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product({ unitPriceCents: -1 }), 1)).toThrow(
        RangeError,
      );
    });
  });

  describe("remove", () => {
    it("removes a product and returns true", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(cart.remove("p1")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("unknown")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product(), 3);
      cart.updateQuantity("p1", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(product(), 3);
      cart.updateQuantity("p1", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 5)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(() => cart.updateQuantity("p1", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      cart.add(product({ id: "p2", name: "Gadget" }), 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of cart lines", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("p1");
      expect(snap[0].quantity).toBe(2);
    });

    it("mutations to snapshot do not affect cart", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(product({ id: "a", unitPriceCents: 500 }), 2);
      cart.add(product({ id: "b", unitPriceCents: 300 }), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(1900);
    });

    it("applies discount via injected policy", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(200);
      expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(1000);
    });

    it("clamps discount to [0, subtotal]", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(9999),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product({ unitPriceCents: 500 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(product({ unitPriceCents: 500 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({ discountPolicy, taxCalculator, region: "US-CA" });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      // tax is computed on discounted subtotal: 1000 - 200 = 800
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
      expect(totals.taxCents).toBe(80);
    });

    it("computes shipping against discounted subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
      expect(totals.shippingCents).toBe(500);
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(72),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      // subtotal=1000, discount=100, discounted=900, tax=72, shipping=500
      expect(totals.totalCents).toBe(900 + 72 + 500);
    });

    it("empty cart returns all zeros", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("uses default region US when not specified", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(product(), 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(
        expect.any(Number),
        "US",
      );
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(product(), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(product(), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });
});

